import type { FileMap } from "./agent";

// Self-hosted webfonts, vendored once into this repo and seeded into every
// new project's public/fonts/ directory (lib/foundation.ts) so a real .woff2
// file exists at a same-origin path in every generated site's build output.
//
// Source: github.com/google/fonts (SIL Open Font License) -- the original
// variable TTFs live under ofl/<family>/ in that repo; the license text for
// each family vendored here is kept alongside it in lib/fonts/licenses/.
// Each family's variable font was pinned to a single static weight with
// fonttools varLib.instancer, then subsetted to Latin + Latin Extended-A and
// compressed to woff2 with fonttools subset --flavor=woff2 -- the same
// pipeline Google Fonts itself uses to produce the hosted woff2 files, just
// run locally so nothing is fetched from a Google host at build or serve time.
//
// Total vendored size: ~347 KB across 16 files (4 families x 4 weights).
//
// Content is base64 -- lib/build-site.ts writes/reads .woff2 as binary via this
// encoding (FileMap is Record<string, string>, so binary content has to travel
// as text); the site and preview serving routes decode it back before sending
// the response.
export const FONT_FILES: FileMap = {
  "public/fonts/baloo-2-400.woff2": "",
  "public/fonts/baloo-2-500.woff2": "",
  "public/fonts/baloo-2-600.woff2": "",
  "public/fonts/baloo-2-700.woff2": "",
  "public/fonts/fraunces-400.woff2": "",
  "public/fonts/fraunces-500.woff2": "",
  "public/fonts/fraunces-600.woff2": "",
  "public/fonts/fraunces-700.woff2": "",
  "public/fonts/space-grotesk-400.woff2": "",
  "public/fonts/space-grotesk-500.woff2": "",
  "public/fonts/space-grotesk-600.woff2": "",
  "public/fonts/space-grotesk-700.woff2": "",
  "public/fonts/work-sans-400.woff2": "",
  "public/fonts/work-sans-500.woff2": "",
  "public/fonts/work-sans-600.woff2": "",
  "public/fonts/work-sans-700.woff2": "",
};
